export const BODY: string = "\n<p>إضافة حد إلى صورة تستغرق دقائق معدودة فقط. ارفع الصورة واختر أسلوبًا واضبط الحجم واللون ونزّل النتيجة المؤطرة.</p>\n<p>في هذا البرنامج التعليمي نمر بالعملية كاملة خطوة بخطوة. سنرى الأساليب الصلبة وبولارويد والتوهج المتدرج ونصف قطر الزاوية والظلال وإعدادات التصدير التي تحافظ على الإطار بمظهر جيد.</p>\n<p>في النهاية ستستطيع تأطير صورة لوسائل التواصل أو طباعة أو قائمة منتج على أي جهاز. واحتفظ بالصورة الأصلية حتى تراجع النتيجة.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: اختر المظهر</h2>\n<p>قرر ما الغرض من الحد قبل فتح الأداة. منشور اجتماعي يحتاج إطارًا رفيعًا ونظيفًا، بينما طباعة تحتاج حدًا أعرض بأسلوب مات.</p>\n<p>وفكر أيضًا في اللون. الأبيض هو الخيار الآمن، والأسود يضيف دراما، ولون مطابق للصورة يعطي إحساسًا مصممًا. واستخدم الصورة الأصلية لا نسخة مضغوطة، فحد مضاف إلى أصل حاد يبدو نظيفًا.</p>\n<p>افتح <a href=\"/ar/idafa-itar-ila-as-sura/\">مولد الحدود للصور</a> في متصفحك. كل شيء يعمل محليًا، فصورتك لا تُرفع أبدًا إلى خادم.</p>\n<h2 id=\"step-by-step\">كيف تضيف حدًا في ست خطوات</h2>\n<p>العملية نفسها لكل أسلوب حد. ارفع واختر الأسلوب واضبط الحجم واللون وراجع المعاينة ونزّل.</p>\n<p>خذ وقتك مع الحجم واللون. هذان الضبطان يقرران هل يؤطر الحد الصورة أم يطغى عليها. وافتح الملف المنزّل مرة قبل مشاركته، وتأكد من أن الحد موحد في كل الجوانب وأن الصورة بداخله ما زالت تبدو جيدة.</p>\n<ol>\n<li>ارفع صورتك بسحبها إلى منطقة الرفع أو اختيارها من جهازك أو لصق لقطة شاشة بـCtrl+V.</li>\n<li>اختر أسلوب حد: صلب أو بولارويد أو توهج متدرج، أو ابدأ من أحد إعدادات الإطار السريعة الأربعة.</li>\n<li>اضبط حجم الحد بين 1 بالمئة و25 بالمئة، واختر لون الإطار المناسب لصورتك.</li>\n<li>اضبط نصف قطر الإطار ونصف قطر الصورة للزوايا المدورة، وأضف ظلًا إذا أردت عمقًا.</li>\n<li>راجع النتيجة، ناظرًا إلى الزوايا والظل على خلفيات فاتحة وداكنة.</li>\n<li>اختر صيغة التصدير، PNG أو WebP للحفاظ على الشفافية والظلال، ثم انقر تنزيل.</li>\n</ol>\n<h2 id=\"choosing-border-style\">كيف تختار أسلوب الحد</h2>\n<p>الحد الصلب شريط بلون واحد وعرض موحد. إنه أبسط أسلوب، ويناسب كل صورة تقريبًا، من البورتريه إلى صور المنتجات.</p>\n<p>حد بولارويد يحاكي الفيلم الفوري، بشريط أسمك في الأسفل لتعليق. يبدو حنينًا وعارضًا، ما يناسب صور العطلات والذكريات. أما إطار التوهج المتدرج فيمزج ألوانًا حول الصورة لمظهر عصري رقمي، ويناسب الرسوم الاجتماعية والملصقات حيث الإطار جزء من التصميم.</p>\n<h2 id=\"setting-border-size\">كيف تضبط حجم الحد</h2>\n<p>حجم الحد يتراوح من 1 بالمئة إلى 25 بالمئة من الصورة. حد رفيع 1 إلى 3 بالمئة يؤطر الصورة دون سحب الانتباه منها.</p>\n<p>حد متوسط 5 إلى 10 بالمئة يخلق إحساسًا بالمعرض. يعطي الصورة مساحة للتنفس ويناسب الطباعات والمحافظ وشرائح العروض. وحد كبير فوق 15 بالمئة يتحول إلى بيان تصميمي، ويناسب الملصقات والرسوم الاجتماعية حيث الإطار جزء من المظهر.</p>\n<h2 id=\"choosing-colour\">كيف تختار لون الحد</h2>\n<p>الأبيض هو لون الحد الآمن. يناسب أي صورة ويعمل على أي خلفية ويعطي الصورة إحساس معرض نظيفًا لا يبدو قديمًا أبدًا.</p>\n<p>الأسود يضيف دراما وتركيزًا. يناسب صور المزاج الداكن واللقطات الليلية والفن، حيث حد فاتح سيبدو في غير مكانه. وطابق الحد مع لون من الصورة لمظهر مصمم: حد يأخذ لون فستان أو سماء أو منتج يربط الإطار بالصورة.</p>\n<h2 id=\"setting-corner-radius\">كيف تضبط نصف قطر الزاوية</h2>\n<p>نصف قطر الإطار يتحكم في تدوير الحافة الخارجية للحد، بينما نصف قطر الصورة يتحكم في تدوير الحافة الداخلية حيث يلتقي الحد بالصورة.</p>\n<p>تثبيت كليهما على القيمة نفسها يعطي إطارًا مدورًا موحدًا. والنتيجة منحنى نظيف ومتسق يبدو احترافيًا في البطاقات والمنشورات الاجتماعية. ولإطار مربع بسيط، أبقِ كلا نصفي القطر صفرًا، فالزوايا الحادة تناسب الصور الرسمية وصور المنتجات.</p>\n<h2 id=\"adding-drop-shadow\">كيف تضيف ظلًا</h2>\n<p>الظل يضيف حافة داكنة ناعمة خلف الصورة المؤطرة، ما يجعلها تبدو طافية فوق الصفحة. يضيف عمقًا وصقلًا.</p>\n<p>الظلال تعمل أفضل على خلفيات فاتحة، حيث تكون الحافة الداكنة مرئية. وعلى خلفية داكنة، يندمج الظل ويضيف قليلًا إلى الصورة. وللحفاظ على الظل، صدّر بصيغة PNG أو WebP، فـJPG لا شفافية فيه، لذا يختفي الظل في تصدير JPG وتبدو النتيجة مسطحة.</p>\n<h2 id=\"using-quick-presets\">كيف تستخدم إعدادات الإطار السريعة</h2>\n<p>تضم الأداة أربعة إعدادات إطار سريعة، كل منها يثبت الأسلوب والحجم واللون والظل بنقرة واحدة. إنها نقطة بداية سريعة للمظاهر الشائعة.</p>\n<p>انقر الإعدادات لترى أيها يناسب صورتك. المعاينة تتحدث فورًا، فتستطيع مقارنة المظاهر في ثوانٍ. وبعد النقر على إعداد، غيّر أي ضبط تريده: اللون والحجم والظل كلها قابلة للضبط، فالإعداد قاعدة لا إجابة نهائية. ولمظهر متسق في مجموعة صور، استخدم الإعداد نفسه لكلها.</p>\n<h2 id=\"polaroid-border\">كيف تصنع حد بولارويد</h2>\n<p>اختر أسلوب بولارويد في خيارات الحد. تطبق الأداة الشكل الكلاسيكي تلقائيًا، بما فيه الشريط الأسمك في الأسفل.</p>\n<p>الشريط السفلي يعطي مساحة لتعليق. أضف نصًا هناك باستخدام <a href=\"/ar/idafa-nass-ila-as-sura/\">أداة إضافة نص إلى صورة</a> بعد التصدير، أو اتركه فارغًا لمظهر رجعي نظيف. وأبقِ نصف قطر الزاوية منخفضًا لإطار بولارويد، فالمظهر الكلاسيكي للفيلم الفوري له زوايا مربعة، وتدويرها كثيرًا يكسر الإحساس الرجعي.</p>\n<h2 id=\"gradient-glow-frame\">كيف تصنع إطار توهج متدرج</h2>\n<p>اختر أسلوب التوهج المتدرج واضبط الزاوية والألوان. التوهج يمزج لونين أو أكثر حول الصورة، منشئًا حدًا ناعمًا ومتوهجًا.</p>\n<p>تغيير الزاوية يحرك المزج حول الإطار. نفس الألوان يمكن أن تنتج مظاهر مختلفة كثيرة، فجرّب زوايا قليلة وانظر أيها يناسب الصورة. وإطارات التدرج تعمل جيدًا على صور داكنة، حيث يضيف الحد الساطع طاقة. وقد تطغى على صورة فاتحة وهوائية، فاستخدمها عندما تحتاج الصورة دراما.</p>\n<h2 id=\"preview-and-compare\">كيف تراجع المعاينة قبل التنزيل</h2>\n<p>راجع المعاينة دائمًا قبل التنزيل. تحقق من أن الحد موحد في كل الجوانب وأن الزوايا تبدو جيدة وأن اللون يناسب الصورة.</p>\n<p>تعرض المعاينة مربعات رمادية وبيضاء حول الإطار. ذلك النمط يعني الشفافية لا خلفية رمادية، ويظهر أين تكون الصورة شفافة. وراجع الظل على خلفية فاتحة إذا أضفت واحدًا: ظل غير مرئي في معاينة داكنة قد يكون واضحًا على الصفحة البيضاء التي ستعيش فيها الصورة.</p>\n<h2 id=\"choosing-export-format\">كيف تختار صيغة التصدير</h2>\n<p>اختر PNG عندما يكون للإطار زوايا مدورة أو ظل. PNG يحافظ على الشفافية، فتبقى الزوايا شفافة والظل ينجو.</p>\n<p>واختر WebP عندما تريد ملفات صغيرة بشفافية. يعمل جيدًا لصور الويب، رغم أن بعض الأنظمة القديمة ما زالت ترفض الصيغة. واختر JPG فقط لحد مستطيل صلب دون ظل، فـJPG يسطح كل شيء فوق خلفية صلبة، وهذا مقبول لإطار بسيط.</p>\n<h2 id=\"adding-border-on-mobile\">كيف تضيف حدًا على الهاتف أو الجهاز اللوحي</h2>\n<p>تعمل الأداة على شاشات اللمس، فتستطيع تأطير صورة على الهاتف نفسه الذي التقطها. ارفعها من معرضك واختر إعدادًا ونزّل النتيجة.</p>\n<p>الإعدادات السريعة هي أسهل طريق على شاشة صغيرة. لمسة واحدة تثبت الأسلوب والحجم واللون والظل، ويمكنك الضبط من هناك إذا لزم الأمر. وراجع المعاينة بالحجم الكامل قبل التنزيل: حد يبدو جيدًا على شاشة هاتف صغيرة قد يكون سميكًا جدًا أو رفيعًا جدًا عند رؤيته على حاسوب.</p>\n<h2 id=\"troubleshooting\">حل المشاكل الشائعة مع الحدود</h2>\n<p>إذا اختفى الظل، راجع صيغة التصدير. JPG لا شفافية فيه، فالظل ينجو فقط في تصديرات PNG أو WebP.</p>\n<p>وإذا بدت الزوايا مربعة عندما أردتها مدورة، راجع نصف قطر الإطار ونصف قطر الصورة: يجب تثبيت كليهما لإطار مدور موحد. وإذا بدا الحد غير متساوٍ، راجع ضبط الحجم: حد مثبت كنسبة مئوية قد يبدو مختلفًا في صور طويلة وعريضة، فاضبطه حسب الشكل.</p>\n<h2 id=\"framing-screenshots\">كيف تؤطر لقطة شاشة</h2>\n<p>الصق لقطة شاشة مباشرة بـCtrl+V لتتخطى خطوة الحفظ. تظهر الصورة في الأداة فورًا، جاهزة للتأطير.</p>\n<p>حد أبيض رفيع بظل ناعم يجعل لقطة الشاشة تبدو كبطاقة. يفصل لقطة الشاشة عن الصفحة ويجعلها تبدو مصقولة. وأبقِ الحد رفيعًا للقطات الشاشة: إطار سميك يشغل مساحة يحتاجها محتوى اللقطة، خصوصًا عندما يكون نص اللقطة صغيرًا. وصدّر اللقطات المؤطرة بصيغة PNG.</p>\n<h2 id=\"quick-tips\">نصائح سريعة لحدود أفضل</h2>\n<p>ابدأ بإعداد سريع واضبط من هناك. الإطارات السريعة تعطيك قاعدة جيدة بنقرة واحدة، والصقل يستغرق ثواني معدودة.</p>\n<p>أبقِ الحد رفيعًا لوسائل التواصل: إطار سميك يشغل مساحة في معاينة خلاصة صغيرة، تاركًا مكانًا أقل للصورة نفسها. واستخدم أسلوب الحد نفسه في مجموعة صور، فالاتساق يجعل السلسلة تبدو احترافية، بينما الإطارات المختلطة تبدو عشوائية. واحفظ الصورة الأصلية دون حد.</p>\n<h2 id=\"border-for-presentation\">كيف تضيف حدًا إلى صورة شريحة عرض تقديمي</h2>\n<p>الصورة المستخدمة في شريحة تحتاج غالبًا حدًا لفصلها عن خلفية الشريحة. إطار أبيض رفيع بظل ناعم يجعل الصورة تبدو كبطاقة على الشريحة.</p>\n<p>أبقِ الحد رفيعًا للشرائح: إطار سميك يشغل مساحة تحتاجها الصورة والنص، خصوصًا عندما تحمل الشريحة عنوانًا ونقاطًا. وطابق لون الحد مع سمة الشريحة: حد أبيض يناسب سمة فاتحة، وحد داكن يناسب سمة داكنة، وإطار لا يطابق يبدو حادثًا. وصدّر الصورة المؤطرة للشريحة بصيغة JPG بجودة عالية.</p>\n<p>لأفكار الأسلوب، اقرأ <a href=\"/ar/blog/anmat-itur-wa-hawaf-as-suwar/\">إطارات وحدود الصور: أنماط لوسائل التواصل والطباعة</a>. وللدليل الكامل، راجع <a href=\"/ar/blog/dalil-munshi-itur-as-suwar/\">الحدود للصور: الدليل الكامل</a>، ولتدوير زوايا صورة جرّب <a href=\"/ar/tadweer-zawaya-as-sura/\">أداة تدوير زوايا الصورة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أضيف حدًا أبيض حول صورة؟","answer":"ارفع الصورة واختر الأسلوب الصلب وثبت اللون على الأبيض واختر حجمًا 1 إلى 3 بالمئة لإطار رفيع أو 5 إلى 10 بالمئة لإحساس معرض. وراجع النتيجة وصدّر بصيغة JPG لإطار مستطيل بسيط أو PNG إذا أضفت ظلًا."},{"question":"هل يمكنني إضافة حد إلى لقطة شاشة على هاتفي؟","answer":"نعم، افتح مولد الحدود في متصفح هاتفك وارفع اللقطة من معرضك والمس إعدادًا سريعًا لإطار فوري. حد أبيض رفيع بظل ناعم يجعل اللقطة تبدو كبطاقة مصقولة."},{"question":"لماذا تعرض المعاينة مربعات رمادية حول إطاري؟","answer":"المربعات تعني الشفافية لا خلفية رمادية. تظهر أين تكون الصورة شفافة، مثل حول الزوايا المدورة أو خلف ظل. وصدّر بصيغة PNG أو WebP للحفاظ على تلك الشفافية."},{"question":"أي حجم حد أستخدم لمنشور إنستغرام؟","answer":"حد رفيع 1 إلى 3 بالمئة يعمل أفضل، لأن إطارًا سميكًا يشغل مساحة في معاينة خلاصة صغيرة. وأبقِ الأسلوب متسقًا في منشوراتك ليكون لخلاصتك مظهر معروف."},{"question":"هل يمكنني تغيير اللون بعد النقر على إعداد سريع؟","answer":"نعم، الإعدادات تثبت الأسلوب والحجم واللون والظل كنقطة بداية، وكل ضبط يبقى قابلًا للضبط بعدها. انقر إعدادًا ثم غيّر لون الإطار أو أي ضبط آخر يناسب صورتك."},{"question":"هل إضافة حد تقص أي جزء من صورتي؟","answer":"لا، فالحد يضيف بكسلات حول الصورة بدل إزالتها، فلا يُقص شيء من الصورة. والصورة النهائية أكبر من الأصل بعرض الحد في كل جانب."}];
